using System.Linq;
using UnityEngine;
public class B05SmokeDriver : MonoBehaviour
{
 const string Root="C:/Users/guan/Documents/unitytest/B05Validation";CombatSession s;int phase;float began;bool read;string lost;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Setup(){var args=Environment.GetCommandLineArgs();if(args.Contains("-b05-smoke")||args.Contains("-b05-read")){var d=new GameObject("B05 validation only").AddComponent<B05SmokeDriver>();d.read=args.Contains("-b05-read");d.began=Time.realtimeSinceStartup;}}
 void Need(bool b,string m){if(!b)throw new Exception(m);}
 void SafeFixture(){for(int n=0;n<s.enemies.Length;n++){var e=s.enemies[n];e.enabled=n==0;e.RestoreState(new SavedEnemy{position=new Vector3(30+n,.1f,30),health=e.Health.maxHealth});var boss=e.GetComponent<BossBrain>();if(boss!=null)boss.enabled=false;}}
 void End(string marker){Need(s.Saves.SaveProgress(false),"Player final save");var f=s.Flow;File.WriteAllText(Root+"/"+marker+".txt","PASS\nwarehouse="+f.Profile.warehouse.Length+"\nsettlements="+f.Profile.committedRuns.Length+"\nactiveRun="+f.ActiveRun?.runId+"\npotions="+s.hero.Inventory.HealthPotionCount+"\nUnity="+Application.unityVersion);Debug.Log(marker+" PASS");enabled=false;Application.Quit(0);}
 void Update(){try{
 if(Time.realtimeSinceStartup-began>90)throw new Exception("Player timeout phase="+phase);if(s==null){if(Time.time<.4f)return;s=UnityEngine.Object.FindAnyObjectByType<CombatSession>();if(s==null)return;s.hero.enabled=false;s.Saves.InitializeStorage(Root+"/player-profile",read);s.Saves.autoSaveInterval=10000;
 if(read){Need(s.Flow.ActiveRun!=null&&s.Flow.ActiveRun.runId==File.ReadAllText(Root+"/player-run-id.txt")&&s.Flow.Profile.warehouse.Length==1&&s.Flow.Profile.committedRuns.Length==2&&s.hero.Inventory.HealthPotionCount==1&&s.Flow.ActiveRun.earnedRemaining[5]==3,"Player same-Run restart mismatch");End("PLAYER_RESTART");return;}
 Need(s.Flow.AtCamp&&s.hero.GetComponent<FantasyActorVisual>().model!=null,"Player camp/model");s.hero.Inventory.RestoreInventory(new[]{3,6,0,10,10,10},2,true,0);Need(s.Flow.Depart(AdventureMode.TestChallenge),"Player departure");SafeFixture();phase=1;return;}
 var f=s.Flow;var b=s.hero.Inventory;var g=s.hero.GetComponent<AdventureLoadout>();
 if(phase==1){var start=s.hero.transform.position;s.hero.GetComponent<CharacterController>().Move(Vector3.forward);Need(Vector3.Distance(start,s.hero.transform.position)>.5f&&s.hero.GetComponent<AdventureCombat>().Strike(),"Player movement/attack");var node=UnityEngine.Object.FindObjectsByType<AdventureResource>(FindObjectsSortMode.None).First(n=>n.kind==MaterialKind.Wood);node.Hit(10000,s.hero);Need(node.Health==0,"Resource harvest");var harvest=UnityEngine.Object.FindObjectsByType<LootPickup>(FindObjectsSortMode.None).First(l=>l.Gear==null&&l.Kind==MaterialKind.Wood);s.hero.RestorePosition(harvest.SavePosition-Vector3.forward*.5f,0);Need(harvest.PickUp(b),"Harvest pickup");int nodeId=node.nodeId;
 s.hero.RestorePosition(new Vector3(0,.1f,-7),0);var p=LootPickup.SpawnGear(AdventureItems.New(GearType.Accessory,GearQuality.Red),s.hero.transform.position+Vector3.forward);Need(p.PickUp(b),"Player equipment loot");var wood=LootPickup.Spawn(MaterialKind.Wood,9,s.hero.transform.position+Vector3.right);Need(wood.PickUp(b),"Player material loot");s.Events.RestoreEvents(new[]{new SavedWorldEvent{kind=WorldEventKind.Treasure,position=new Vector3(0,0,-5)}});Need(s.Events.Points[0].Interact(s.hero),"Player chest open");Need(s.Saves.SaveProgress(false)&&s.Saves.LoadProgress(false),"Player checkpoint roundtrip");Need(UnityEngine.Object.FindObjectsByType<AdventureResource>(FindObjectsSortMode.None).Single(n=>n.nodeId==nodeId).Health==0&&s.Events.Points[0].Used&&!s.Events.Points[0].Interact(s.hero),"World reward source refreshed");Debug.Log("B05_V17_PLAYER_RESOURCE_CHEST_PICKUP_CHECKPOINT_PASS");SafeFixture();s.hero.RestorePosition(f.ExitPosition,0);Need(s.enemies.Any(e=>!e.Health.Dead)&&f.BeginExtraction()&&f.ActiveRun.extractionRemaining==5,"Player live-enemy exit");phase=2;return;}
 if(phase==2){if(f.Settlement==null)return;Need(f.CommitSettlement()&&f.AcknowledgeSettlement()&&f.Profile.warehouse.Length==1&&f.Profile.materials[3]>=9,"Player success settle");string item=f.Profile.warehouse[0].id;Need(s.Camp.WithdrawEquipment(item)&&s.Camp.DepositEquipment(item)&&s.Camp.TransferMaterial(MaterialKind.Wood,9,false)&&g.Craft(GearType.Sword,GearQuality.White),"Player camp store/withdraw/manufacture");Need(f.Depart(AdventureMode.TestChallenge),"Player second depart");SafeFixture();phase=3;return;}
 if(phase==3){var p=LootPickup.SpawnGear(AdventureItems.New(GearType.Armor,GearQuality.Red),s.hero.transform.position+Vector3.forward);lost=p.Gear.id;Need(p.PickUp(b)&&g.AutoMove(g.items.Single(i=>i.id==lost)),"Player worn loot");s.hero.Health.Damage(30);Need(b.UseHealthPotion()&&b.HealthPotionCount==1,"Player brought potion use");s.hero.Health.Damage(1000000);phase=4;return;}
 if(phase==4){if(f.Settlement==null)return;Need(f.Settlement.outcome==AdventureOutcome.Death&&f.CommitSettlement()&&f.AcknowledgeSettlement()&&!g.items.Any(i=>i.id==lost)&&b.HealthPotionCount==1,"Player death protected loot/consumable boundary");Need(f.Depart(AdventureMode.EndlessWaves)&&b.Add(MaterialKind.Ore,3),"Player final active Run");File.WriteAllText(Root+"/player-run-id.txt",f.ActiveRun.runId);End("PLAYER_FULL_LOOP");}
 }catch(Exception e){Debug.LogException(e);File.WriteAllText(Root+"/PLAYER_FAIL.txt",e.ToString());enabled=false;Application.Quit(1);}}
